use crate::int::types::traits::BigInt;

/// `ln(1 + idx/M)` at working scale `w`, read from the narrow prefix
/// table into the work integer `W`.
///
/// The reconstruction lives ONCE, in
/// [`crate::algos::support::ln_tang_slot::ln_table_entry_from_slot`];
/// this wrapper only names which slot to read. `idx = 0` is `ln 1 = 0`.
///
/// # Panics
///
/// If `w` demands more than [`LN_TANG_NARROW_LIMBS`] limbs of slot —
/// the validity wall bounding this table against the narrow rung's
/// reach. A silently truncated slot would yield wrong digits.
#[inline]
pub(crate) fn ln_table_entry_narrow<W: BigInt>(w: u32, idx: usize, pow10_w: W) -> W {
    if idx == 0 {
        return W::ZERO;
    }
    crate::algos::support::ln_tang_slot::ln_table_entry_from_slot::<W>(
        w,
        &LN_TANG_SLOTS_NARROW[idx],
        pow10_w,
    )
}

